// A tiling desktop: every scene opened is a tile, all of them running at once, none
// over another (so each is drawn straight into its part of the panel, at its own
// pace). The tiles keep their places in the arrangement the top bar's button steps
// through (its glyph is the one in use): the first large on the left and the rest in
// a column, the first on top and the rest in a row, an even grid, columns, rows.
// Drag the gap between tiles to move that split (kept per arrangement). A press
// anywhere in a tile is that scene's at once (a button in it works on the first
// press) and gives it the focus, which its bar's color marks. Drag a tile by its
// bar onto another, bar or picture, to swap the two. A tile's
// bar has a gear for its scene's settings, which open as a tile of their own (one a
// scene, several at once), a cross that closes it, and on the focused tile a corner
// that gives it the whole desktop until pressed again. The top bar's + lists the
// frame's scenes to open (a new tile, at the end), its names give a tile the focus
// where it is, its bag opens the scene store where the frame has it, and its gear
// opens the frame's settings (Control Panel). The frame's
// own scenes (a scene's settings, the frame's, the scene list, the terminal) are
// tiles too, with a plain icon for a gear, and close when they go back by
// themselves (Save, Cancel, a scene picked). Chosen in another desktop's place (the
// frame page's Layout), it opens what that one had open, as tiles.
//
// On a frame that runs one scene at a time (an ESP32, the preview: no
// app.frame.scenes), it is a bar above the scene.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// Drawn, not typed: a font need not have these.
const Glyph = ({ d, color, size }) => (
  <svg viewBox="0 0 10 10" className={`w-[${size}px] h-[${size}px]`}>
    <path fill="none" stroke={color} strokeWidth="1.4" d={d} />
  </svg>
)
const CLOSE = 'M1.5 1.5L8.5 8.5M8.5 1.5L1.5 8.5'
const GROW = 'M1 4V1H4M6 1H9V4M9 6V9H6M4 9H1V6'
const SHRINK = 'M4 1V4H1M9 4H6V1M6 9V6H9M1 6H4V9'
const GEAR = 'M5 1.2V2.6M5 7.4V8.8M1.2 5H2.6M7.4 5H8.8M2.3 2.3L3.3 3.3M6.7 6.7L7.7 7.7M7.7 2.3L6.7 3.3M3.3 6.7L2.3 7.7M3.4 5a1.6 1.6 0 1 0 3.2 0a1.6 1.6 0 1 0 -3.2 0'
const PROMPT = 'M1.5 2.5L4.5 5L1.5 7.5M5.5 8H9'
const GRID = 'M1 1H4V4H1ZM6 1H9V4H6ZM1 6H4V9H1ZM6 6H9V9H6Z'
const GEAR_FILLED =
  'M20 9L21 3L27 3L28 9L32 11L36 7L41 12L37 16L39 20L45 21L45 27L39 28L37 32L41 36L36 41L32 37L28 39L27 45L21 45L20 39L16 37L12 41L7 36L11 32L9 28L3 27L3 21L9 20L11 16L7 12L12 7L16 11ZM17 24a7 7 0 1 0 14 0a7 7 0 1 0 -14 0Z'

// ------------------------------------------------------------ the frame's pages
//
// The frame's own pages (a scene's settings, the frame's, the scene list, the
// terminal, the keyboard on the screen) in this layout's look: a theme is each
// kind of element's classes (docs/jsx-ui.md "Themes"), a string for one box or a
// list for boxes inside each other (a bevel is two or three, as a box has one
// border color). The layout keeps it in its state as `theme`, where the frame
// reads it; not on an ESP32, where the pages keep their own look, nor on e-paper
// but for high contrast.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
  terminal: 'bg-black text-white',
  prompt: 'font-bold text-[#ffff00]',
}

function dress(app, themes, fallback) {
  if (app.frame.embedded) return
  const name = String(app.state.look || fallback)
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : themes[name] || null
  const key = theme ? name : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

const THEMES = {}

const openOf = (app) => (Array.isArray(app.state.open) ? app.state.open : [])
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// The frame's own scenes (the contract's `scenes.*`). On a desktop every scene's
// settings are a scene of their own, this and the scene's id (`scenes.settingsWindow`);
// the plain settings id is the frame's page. The command that opens a built-in
// scene sends it back.
const SETTINGS = 'system/sceneSettings'
const SWITCHER = 'system/sceneSwitcher'
const TERMINAL = 'system/terminal'
const SETTINGS_OF = 'system/sceneSettings#'
const settingsOf = (id) => SETTINGS_OF + id
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const commandOf = (id) => (id === SWITCHER ? 'sceneSwitcher' : id === TERMINAL ? 'terminal' : 'sceneSettings')
// The scene store (docs/scene-store.md) is a scene the frame may have, not one of
// its own: the sample's id, or its name where a control plane gave it another id.
// A desktop has an entry of its own for it, and leaves it out of the scene lists.
const isStore = (scene) =>
  !!scene && (scene.id === 'scene-store' || String(scene.name || '').trim().toLowerCase() === 'scene store')
const storeOf = (app) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(isStore) : undefined)
const BAG = 'M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z'

const Bar = ({ app, height, children }) => {
  const now = new Date()
  return (
    <div
      className={`flex items-center h-[${height}px] gap-[${Math.round(height / 3)}px] px-[${Math.round(height / 3)}px] bg-[${app.state.barColor}] text-[${app.state.textColor}] text-[${Math.round(height * 0.55)}px]`}
    >
      {children}
      <span className="font-semibold">{`${pad(now.getHours())}:${pad(now.getMinutes())}`}</span>
    </div>
  )
}

// A raised button with a gear, as a window's title bar has one: a tile's scene's
// settings. It takes its press itself, so the bar under it starts no drag.
const GearButton = ({ size, onClick }) => (
  <div className="flex bg-[#c0c0c0] active:bg-[#909090] border-t-1 border-l-1 border-white active:border-black" onPointerDown={() => {}} onClick={onClick}>
    <div className="flex border-b-1 border-r-1 border-black active:border-white">
      <div className={`flex items-center justify-center w-[${Math.round(size * 1.25)}px] h-[${size}px] border-b-1 border-r-1 border-[#808080]`}>
        <svg viewBox="0 0 48 48" className={`w-[${Math.round(size * 0.75)}px] h-[${Math.round(size * 0.75)}px]`}>
          <path fill="#000000" d={GEAR_FILLED} />
        </svg>
      </div>
    </div>
  </div>
)

// The arrangements the top bar's button steps through, and each one's glyph.
const ARRANGEMENTS = ['side', 'top', 'grid', 'columns', 'rows']
const ARRANGEMENT_GLYPHS = {
  side: 'M1 1H5V9H1ZM6 1H9V4.5H6ZM6 5.5H9V9H6Z',
  top: 'M1 1H9V5H1ZM1 6H4.5V9H1ZM5.5 6H9V9H5.5Z',
  grid: 'M1 1H4.5V4.5H1ZM5.5 1H9V4.5H5.5ZM1 5.5H4.5V9H1ZM5.5 5.5H9V9H5.5Z',
  columns: 'M1 1H3V9H1ZM4 1H6V9H4ZM7 1H9V9H7Z',
  rows: 'M1 1H9V3H1ZM1 4H9V6H1ZM1 7H9V9H1Z',
}
const arrangementOf = (app) => (ARRANGEMENTS.includes(app.state.arrangement) ? app.state.arrangement : 'side')

// Shares of a length, one a part: the ones kept when they are as many, else even.
const sharesOf = (kept, n) =>
  Array.isArray(kept) && kept.length === n && kept.every((f) => typeof f === 'number' && f > 0) ? kept : Array.from({ length: n }, () => 1 / n)

// Where the tiles go, in the desktop's pixels, and the gaps between them that move a
// split: `along` the axis a gap moves on, `at` where it is, `lo` and `hi` the ends of
// the two parts it splits, `split` the shares kept in `splits` (the large tile's
// own, `side` or `top`; the tiles beside it, `sideRest` or `topRest`; a grid's rows,
// `grid`, and each row's tiles, `grid0`, `grid1`…), `index` its part and `count`
// how many parts share it.
function arrange(kind, ids, w, h, splits) {
  const boxes = {}
  const gaps = []
  const n = ids.length
  // `parts` of the span from `from` to `from + size`, by their shares, on an axis.
  const lay = (parts, shares, horizontal, from, size, cross, crossSize, split) => {
    let sum = 0
    parts.forEach((id, i) => {
      const a = from + Math.round(sum * size)
      sum += shares[i]
      const b = i === parts.length - 1 ? from + size : from + Math.round(sum * size)
      boxes[id] = horizontal ? { x: a, y: cross, w: b - a, h: crossSize } : { x: cross, y: a, w: crossSize, h: b - a }
      if (split && i < parts.length - 1) {
        const end = i + 1 === parts.length - 1 ? from + size : from + Math.round((sum + shares[i + 1]) * size)
        gaps.push({
          along: horizontal ? 'x' : 'y', at: b, lo: a, hi: end, total: size, from, cross, crossSize, split, index: i,
          count: parts.length,
        })
      }
    })
  }
  if (n === 1) boxes[ids[0]] = { x: 0, y: 0, w, h }
  else if (n > 1 && (kind === 'side' || kind === 'top')) {
    const across = kind === 'side'
    const main = typeof splits[kind] === 'number' ? splits[kind] : 0.6
    const size = across ? w : h
    const first = Math.round(main * size)
    boxes[ids[0]] = across ? { x: 0, y: 0, w: first, h } : { x: 0, y: 0, w, h: first }
    const rest = `${kind}Rest`
    lay(ids.slice(1), sharesOf(splits[rest], n - 1), !across, 0, across ? h : w, first, size - first, rest)
    gaps.push({ along: across ? 'x' : 'y', at: first, lo: 0, hi: size, total: size, from: 0, cross: 0, crossSize: across ? h : w, split: kind, index: -1 })
  } else if (n > 1 && kind === 'grid') {
    // As square as the count allows; the last row's tiles share what it leaves.
    const cols = Math.ceil(Math.sqrt(n))
    const rows = Math.ceil(n / cols)
    const shares = sharesOf(splits.grid, rows)
    const rowIds = Array.from({ length: rows }, (_, r) => ids.slice(r * cols, r * cols + cols))
    lay(rowIds.map((_, r) => `row${r}`), shares, false, 0, h, 0, w, 'grid')
    rowIds.forEach((row, r) => {
      const band = boxes[`row${r}`]
      delete boxes[`row${r}`]
      lay(row, sharesOf(splits[`grid${r}`], row.length), true, 0, w, band.y, band.h, `grid${r}`)
    })
  } else if (n > 1) {
    lay(ids, sharesOf(splits[kind], n), kind === 'columns', 0, kind === 'columns' ? w : h, 0, kind === 'columns' ? h : w, kind)
  }
  return { boxes, gaps }
}

export function get(app) {
  frameos.setNextSleep(60 - new Date().getSeconds())
  dress(app, THEMES, 'frameos')
  const accent = app.state.accent
  const current = app.frame.sceneId
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const barH = Math.max(22, Math.round(height * 0.05))
  if (!Array.isArray(app.frame.scenes)) {
    return (
      <div className="flex flex-col w-full h-full bg-black">
        <Bar app={app} height={barH}>
          <span className="flex-1 truncate">{app.frame.sceneName}</span>
        </Bar>
        <yield />
      </div>
    )
  }
  const scale = app.frame.scale || 1
  const tileBarH = Math.max(16, Math.round(height * 0.036))
  const glyph = Math.max(8, Math.round(tileBarH * 0.5))
  const deskW = width
  const deskH = Math.max(1, height - barH)

  const sceneNames = {}
  for (const scene of app.frame.scenes) sceneNames[scene.id] = scene.name || scene.id
  // A built-in scene's tile is named by what it shows while it has the focus; a
  // scene's own settings by their scene.
  const titles = { ...(app.state.titles || {}) }
  const owner = settingsFor(current)
  const title = owner ? `${sceneNames[owner] || owner} settings` : app.frame.sceneName
  // A layout just chosen in another desktop's place has no tiles of its own yet: it
  // opens what that one had open (its `openScenes`, handed over by the runtime:
  // docs/scene-layouts.md "Windows"), in that order, the frame's own scenes named by
  // what they are until they show their page here.
  const fresh = !Array.isArray(app.state.open)
  const carried = fresh && Array.isArray(app.state.openScenes) ? app.state.openScenes.filter((id) => typeof id === 'string') : []
  let named = false
  for (const id of carried) {
    if (!isSystem(id) || titles[id]) continue
    const scene = settingsFor(id)
    titles[id] = scene
      ? `${sceneNames[scene] || scene} settings`
      : id === TERMINAL ? 'Terminal' : id === SWITCHER ? 'Scene switcher' : 'Frame settings'
    named = true
  }
  if (app.frame.systemScene && titles[current] !== title) {
    titles[current] = title
    named = true
  }
  if (named) frameos.setState('titles', titles)
  const names = { ...titles, ...sceneNames }
  if (current && !names[current]) names[current] = app.frame.sceneName || current

  // The scene with the focus, however it got it, has a tile (a new one at the
  // end); what was open stays where it is. A built-in scene that lost the focus to
  // a scene without this layout asking went back by itself: its tile closes.
  const saved = fresh ? carried.filter((id, i) => carried.indexOf(id) === i) : openOf(app)
  let open = saved.filter((id) => names[id])
  if (app.state.last !== current) {
    if (isSystem(app.state.last) && !isSystem(current) && app.state.asked !== current)
      open = open.filter((id) => id !== app.state.last)
    if (app.state.asked) frameos.setState('asked', null)
    frameos.setState('last', current)
  }
  if (current && !open.includes(current) && app.state.gone !== current) open.push(current)
  if (fresh || open.length !== saved.length || open.some((id, i) => id !== saved[i])) frameos.setState('open', open)
  // What is open, in its order: what a layout chosen in this one's place opens.
  if (JSON.stringify(open) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', open)
  if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)

  // Read when a handler runs: a press before it may have moved the focus.
  const showing = () => app.frame.sceneId
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  // The focus, where the tile is.
  const focus = (id) => {
    frameos.setState('adding', false)
    if (id !== showing()) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // A built-in scene with the focus closes as its own Cancel does.
  const close = (id) => {
    const rest = openOf(app).filter((other) => other !== id)
    frameos.setState('open', rest)
    if (id !== showing()) return
    frameos.setState('gone', id)
    frameos.setState('zoomed', false)
    if (isSystem(id)) frameos.dispatch(commandOf(id))
    else if (rest.length) go(rest[rest.length - 1])
  }
  // A tile's gear: its scene's settings, a tile of their own, opened over the scene
  // given the focus first; open already, that tile gets the focus.
  const sceneSettings = (id) => {
    frameos.setState('adding', false)
    if (openOf(app).includes(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // The top bar's gear: the frame's settings, one tile. Over a built-in tile with
  // the focus, a scene's tile gets it first, so that one stays open.
  const controlPanel = () => {
    frameos.setState('adding', false)
    if (openOf(app).includes(SETTINGS)) return focus(SETTINGS)
    if (isSystem(showing())) {
      const scene = openOf(app).find((id) => !isSystem(id))
      if (scene) go(scene)
    }
    frameos.dispatch('sceneSettings', { page: 'frame' })
    frameos.setState('asked', SETTINGS)
  }
  // The tiles swap places.
  const swap = (a, b) => {
    const next = [...openOf(app)]
    const i = next.indexOf(a)
    const j = next.indexOf(b)
    if (i < 0 || j < 0 || i === j) return
    next[i] = b
    next[j] = a
    frameos.setState('open', next)
  }

  const zoomed = on(app.state.zoomed) && open.includes(current)
  const adding = on(app.state.adding)
  const shown = zoomed ? [current] : open
  const arrangement = arrangementOf(app)
  const splits = app.state.splits && typeof app.state.splits === 'object' ? app.state.splits : {}
  const { boxes, gaps } = arrange(arrangement, shown, deskW, deskH, splits)
  const nextArrangement = () => {
    frameos.setState('adding', false)
    frameos.setState('arrangement', ARRANGEMENTS[(ARRANGEMENTS.indexOf(arrangement) + 1) % ARRANGEMENTS.length])
  }
  // No tile smaller than a few of its bars.
  const least = Math.max(48, tileBarH * 4)
  // A gap between tiles, dragged: the split moves with the pointer, each part kept
  // at least `least`. It takes its press itself, so no scene under it hears one.
  const grab = Math.max(12, Math.round(12 * Math.min(1, scale)))
  const gapHandlers = (gap) => ({
    onPointerDown: () => {
      frameos.setState('adding', false)
      frameos.setState('resizing', { split: gap.split, index: gap.index })
    },
    onPointerMove: (e) => {
      const held = app.state.resizing
      if (!held || held.split !== gap.split || held.index !== gap.index || !e.buttons) return
      const p = gap.along === 'x' ? e.x / scale : e.y / scale - barH
      const at = Math.min(Math.max(p, gap.lo + least), gap.hi - least)
      if (gap.hi - gap.lo < 2 * least) return
      const kept = app.state.splits && typeof app.state.splits === 'object' ? app.state.splits : {}
      let next
      if (gap.index < 0) next = (at - gap.from) / gap.total
      else {
        next = [...sharesOf(kept[gap.split], gap.count)]
        next[gap.index] = (at - gap.lo) / gap.total
        next[gap.index + 1] = (gap.hi - at) / gap.total
      }
      frameos.setState('splits', { ...kept, [gap.split]: next })
    },
    onPointerUp: () => frameos.setState('resizing', null),
  })
  const tileAt = (x, y) => shown.find((id) => {
    const b = boxes[id]
    return b && x >= b.x && x < b.x + b.w && y >= b.y && y < b.y + b.h
  })

  // A tile's bar: a press there gives its tile the focus; dragged away, it is
  // carried to the tile let go over, and the two swap places. While it is held
  // over another tile, an outline says where it would go.
  const drag = app.state.drag
  const slop = Math.max(6, Math.round(tileBarH / 2))
  const barHandlers = (id) => ({
    onPointerDown: (e) => {
      frameos.setState('adding', false)
      frameos.setState('drag', { id, x: e.x, y: e.y, moved: false, at: null })
    },
    onPointerMove: (e) => {
      const held = app.state.drag
      if (!held || held.id !== id || !e.buttons) return
      const moved = held.moved || Math.abs(e.x - held.x) + Math.abs(e.y - held.y) > slop * scale
      const at = moved ? tileAt(e.x / scale, e.y / scale - barH) || null : null
      if (moved !== held.moved || at !== held.at) frameos.setState('drag', { ...held, moved, at })
    },
    onPointerUp: () => {
      const held = app.state.drag
      frameos.setState('drag', null)
      if (!held || held.id !== id) return
      if (!held.moved) focus(id)
      else if (held.at && held.at !== id) swap(id, held.at)
    },
  })

  const Tile = ({ id }) => {
    const b = boxes[id]
    const focused = id === current
    const muted = focused ? '#ffffff' : '#94a3b8'
    return (
      <div
        className={`absolute left-[${b.x}px] top-[${b.y}px] w-[${b.w}px] h-[${b.h}px] flex flex-col border-[2px] ${focused ? `border-[${accent}]` : 'border-[#334155]'}`}
      >
        <div
          className={`flex items-center h-[${tileBarH}px] gap-[${Math.round(tileBarH / 3)}px] px-[${Math.round(tileBarH / 4)}px] text-[${Math.round(tileBarH * 0.6)}px] ${focused ? `bg-[${accent}] text-white` : 'bg-[#1e293b] text-[#94a3b8]'}`}
          {...barHandlers(id)}
        >
          {isSystem(id) ? (
            <Glyph d={id === TERMINAL ? PROMPT : id === SWITCHER ? GRID : GEAR} color={muted} size={glyph} />
          ) : (
            <GearButton size={Math.round(tileBarH * 0.75)} onClick={() => sceneSettings(id)} />
          )}
          <span className="flex-1 truncate">{names[id]}</span>
          {focused ? (
            <span className="px-[2px]" onPointerDown={() => {}} onClick={() => frameos.setState('zoomed', !zoomed)}>
              <Glyph d={zoomed ? SHRINK : GROW} color="#ffffff" size={glyph} />
            </span>
          ) : null}
          <span className="px-[2px]" onPointerDown={() => {}} onClick={() => close(id)}>
            <Glyph d={CLOSE} color={muted} size={glyph} />
          </span>
        </div>
        <div className="relative flex flex-col flex-1 min-h-0">
          {/* The scene with the focus is the frame's own; a press on any other is
              that scene's, and gives it the focus too (the layout's handler on it). */}
          {focused ? <yield /> : <Scene id={id} onPointerDown={() => focus(id)} />}
        </div>
      </div>
    )
  }

  // The scene store has a button of its own in the top bar, out of the + list.
  const store = storeOf(app)
  const closed = app.frame.scenes.filter((scene) => !open.includes(scene.id) && !isStore(scene))
  const target = drag && drag.moved && drag.at && drag.at !== drag.id ? boxes[drag.at] : null
  return (
    <div className="relative flex flex-col w-full h-full bg-[#0f172a]">
      <Bar app={app} height={barH}>
        <span className={`px-[${Math.round(barH / 3)}px] font-bold ${adding ? 'bg-white/20' : ''}`} onClick={() => frameos.setState('adding', !adding)}>
          +
        </span>
        <div className={`flex flex-1 min-w-0 gap-[${Math.round(barH / 3)}px]`}>
          {open.map((id) => (
            <span className={`px-[${Math.round(barH / 3)}px] truncate ${id === current ? `bg-[${accent}] text-white` : 'opacity-70'}`} onClick={() => focus(id)}>
              {names[id]}
            </span>
          ))}
        </div>
        {store ? (
          <span className={`px-[${Math.round(barH / 4)}px] ${store.id === current ? `bg-[${accent}]` : ''}`} onClick={() => focus(store.id)}>
            <svg viewBox="0 0 24 24" className={`w-[${Math.round(barH * 0.6)}px] h-[${Math.round(barH * 0.6)}px]`}>
              <path fill={store.id === current ? '#ffffff' : app.state.textColor} d={BAG} />
            </svg>
          </span>
        ) : null}
        <span className={`px-[${Math.round(barH / 4)}px]`} onClick={nextArrangement}>
          <svg viewBox="0 0 10 10" className={`w-[${Math.round(barH * 0.6)}px] h-[${Math.round(barH * 0.6)}px]`}>
            <path fill={app.state.textColor} d={ARRANGEMENT_GLYPHS[arrangement]} />
          </svg>
        </span>
        <span className={`px-[${Math.round(barH / 4)}px]`} onClick={controlPanel}>
          <Glyph d={GEAR} color={app.state.textColor} size={Math.round(barH * 0.6)} />
        </span>
      </Bar>
      <div className="relative flex-1 min-h-0">
        {shown.map((id) => (
          <Tile id={id} />
        ))}
        {zoomed
          ? null
          : gaps.map((gap) =>
              gap.along === 'x' ? (
                <div className={`absolute left-[${gap.at - grab / 2}px] top-[${gap.cross}px] w-[${grab}px] h-[${gap.crossSize}px]`} {...gapHandlers(gap)} />
              ) : (
                <div className={`absolute left-[${gap.cross}px] top-[${gap.at - grab / 2}px] w-[${gap.crossSize}px] h-[${grab}px]`} {...gapHandlers(gap)} />
              ),
            )}
        {target ? (
          <div className={`absolute left-[${target.x}px] top-[${target.y}px] w-[${target.w}px] h-[${target.h}px] border-[4px] border-white`} />
        ) : null}
      </div>
      {adding ? (
        <div
          className={`absolute left-[${Math.round(barH / 3)}px] top-[${barH}px] flex flex-col min-w-[30vw] bg-[#1e293b] text-white text-[${Math.round(barH * 0.55)}px] border-[2px] border-[#334155]`}
          onPointerDown={() => {}}
        >
          {closed.length ? (
            closed.map((scene) => (
              <span className={`px-[${Math.round(barH / 2)}px] py-[${Math.round(barH / 3)}px] hover:bg-[#334155]`} onClick={() => focus(scene.id)}>
                {scene.name || scene.id}
              </span>
            ))
          ) : (
            <span className={`px-[${Math.round(barH / 2)}px] py-[${Math.round(barH / 3)}px] opacity-60`}>Every scene is open</span>
          )}
        </div>
      ) : null}
    </div>
  )
}
